    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">C = x + 3 - x - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">4</span></span> - x - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">4</span></span> - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> - x + 6 + <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - x + 2x - <span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">3</span></span> - √2</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">C = (x - x - x - x - x + 2x) + (3 - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">4</span></span> - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">4</span></span> - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> + 6 + <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">3</span></span>) - √2</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">C = -x + 3 - √2</span>"}],
