    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">D = y + <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">4</span></span> + y - 3 - y + <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">4</span></span> + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">6</span></span> - √3</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">D = (y + y - y) + (<span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">4</span></span> - 3 + <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">4</span></span> + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">6</span></span>) - √3</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">D = y - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">6</span></span> - √3</span>"}],
