    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">C = -x + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">4</span></span> - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> + x + x - x - √2 + x - 2x + <span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">4</span></span></span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">C = (-x + x + x - x + x - 2x) + (<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">4</span></span> - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> + <span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">4</span></span>) - √2</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">C = -x + 1 - √2</span>"}],
