    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">E = -<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">4</span></span> + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> + b + π + b + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> + π + π + <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> - a - 3b - <span class=\"frac\"><span class=\"num\">59</span><span class=\"den\">12</span></span> - 2π</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">E = -a + (b + b - 3b) + (-<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">4</span></span> + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">59</span><span class=\"den\">12</span></span>) + (π + π + π - 2π)</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = -a - b - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + π</span>"}],
