    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">F = π + 3 - 3 - <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - a + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">5</span></span> - b - <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">10</span></span> - 2π</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">F = -a - b + (3 - 3 - <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">5</span></span> - <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">10</span></span>) + (π - 2π)</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">F = -a - b - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span> - π</span>"}],
