    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">E = -<span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">2</span></span> - π - 2 - π - b - a + 2b + <span class=\"frac\"><span class=\"num\">81</span><span class=\"den\">10</span></span> + 3π</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">E = -a + (-b + 2b) + (-<span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">2</span></span> - 2 + <span class=\"frac\"><span class=\"num\">81</span><span class=\"den\">10</span></span>) + (-π - π + 3π)</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = -a + b + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">5</span></span> + π</span>"}],
