    correction: [{"quoi":"نجمع الشكلين المختصرين","math":"<span dir=\"ltr\" class=\"expr\">E + b + F = -2a - b + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span></span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-2a - b + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> = 0</span>"},{"quoi":"نعزل a","math":"<span dir=\"ltr\" class=\"expr\">-2a = 0 - (-b + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span>)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">0 - (-b + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span>) = b - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a = -<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> b + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span></span>"}],
