    correction: [{"quoi":"نختصر الطرف الأوّل","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> + [-1 - (-3 + x + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span>)] - √3 + [<span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span>] + <span class=\"frac\"><span class=\"num\">41</span><span class=\"den\">12</span></span> + 2√3 = -x + 3 + √3</span>"},{"quoi":"نكتب المعادلة المختصرة","math":"<span dir=\"ltr\" class=\"expr\">-x + 3 + √3 = 4 - √3</span>"},{"quoi":"نعزل x","math":"<span dir=\"ltr\" class=\"expr\">-x = 4 - √3 - (3 + √3)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">4 - √3 - (3 + √3) = 1 - 2√3</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -1 + 2√3</span>"}],
