    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">M = -a - √2 + a - √2 - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">5</span></span> - √2 + √2 + 6 + 3a + 2b - <span class=\"frac\"><span class=\"num\">47</span><span class=\"den\">10</span></span> + 3√2</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">M = (-a + a + 3a) + 2b + (-<span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">5</span></span> + 6 - <span class=\"frac\"><span class=\"num\">47</span><span class=\"den\">10</span></span>) + (-√2 - √2 - √2 + √2 + 3√2)</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 3a + 2b - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + √2</span>"}],
